/// Built-in skills shipped with the fa package (issue #1151): parsing of
/// the compiled-in sources, lowest-precedence discovery merge (project >
/// user > third-party-granted > builtin), first-party access semantics,
/// renderer + read-tool service from the embedded copy.
library;

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/src/skills/skill_renderer.dart';
import 'package:test/test.dart';

void main() {
  late MemoryExecutionEnv env;

  setUp(() {
    env = MemoryExecutionEnv(cwd: '/work');
  });

  group('builtinSkills', () {
    test('the first batch parses with real manifests', () {
      final skills = builtinSkills();
      final names = skills.map((s) => s.name).toSet();
      expect(names, containsAll(['create-goal', 'self-settings']));
      for (final skill in skills) {
        expect(skill.source, SkillSource.builtin);
        expect(skill.scope, SkillScope.builtin);
        expect(skill.embeddedText, isNotNull);
        expect(skill.filePath, startsWith('builtin://skills/'));
        expect(skill.filePath, endsWith('/SKILL.md'));
        expect(skill.description.length, greaterThan(10));
        expect(skill.description, isNot('No description provided.'));
      }
      // The manifests carried over the port: invocation hints and the
      // self-configuration tool grants.
      final createGoal = skills.firstWhere((s) => s.name == 'create-goal');
      expect(createGoal.manifest.argumentHint, isNotNull);
      expect(createGoal.userInvocable, isTrue);
      expect(createGoal.modelInvocable, isTrue);
      final selfSettings = skills.firstWhere((s) => s.name == 'self-settings');
      expect(selfSettings.manifest.plainAllowedTools, contains('config'));
    });

    test('is not gated by the third-party skills-access consent', () {
      for (final skill in builtinSkills()) {
        expect(skillSourceIsThirdParty(skill.source), isFalse);
      }
    });
  });

  group('discoverSkills builtins merge', () {
    test('builtins resolve in a project with NO .fah/skills', () async {
      final skills = await discoverSkills(
        env,
        projectRoots: defaultSkillRoots(
          cwd: '/work',
          homeDir: null,
        ).projectRoots,
        userRoots: const [],
        builtins: builtinSkills(),
      );
      final names = skills.map((s) => s.name).toSet();
      expect(names, containsAll(['create-goal', 'self-settings']));
    });

    test('a project skill of the same name shadows the builtin', () async {
      await env.createDir('/work/.fah/skills/create-goal');
      await env.writeFile(
        '/work/.fah/skills/create-goal/SKILL.md',
        '---\ndescription: project override\n---\nproject body\n',
      );
      final skills = await discoverSkills(
        env,
        projectRoots: const [SkillRoot('/work/.fah/skills', SkillSource.fah)],
        builtins: builtinSkills(),
      );
      final goals = skills.where((s) => s.name == 'create-goal').toList();
      expect(goals, hasLength(1));
      expect(goals.single.source, SkillSource.fah);
      expect(goals.single.description, 'project override');
    });

    test('builtins survive allowedSources restricted to first-party', () async {
      final skills = await discoverSkills(
        env,
        projectRoots: const [
          SkillRoot('/work/.claude/skills', SkillSource.claude),
        ],
        userRoots: const [],
        allowedSources: const {SkillSource.fah, SkillSource.agents},
        builtins: builtinSkills(),
      );
      expect(
        skills.map((s) => s.name),
        containsAll(['create-goal', 'self-settings']),
      );
    });
  });

  group('rendering and read access from the embedded copy', () {
    test('renderSkillBody works without a backing file', () async {
      final skill = builtinSkills().firstWhere((s) => s.name == 'create-goal');
      final rendered = await renderSkillBody(
        env,
        skill,
        args: 'flappy bird clone',
      );
      expect(rendered.body, contains('# Create Goal'));
      expect(rendered.body, isNot(contains(r'$ARGUMENTS')));
    });

    test('builtinSkillTextAt serves the virtual read path', () {
      final skill = builtinSkills().firstWhere((s) => s.name == 'create-goal');
      expect(builtinSkillTextAt(skill.filePath), skill.embeddedText);
      expect(builtinSkillTextAt('builtin://skills/nope/SKILL.md'), isNull);
      expect(builtinSkillTextAt('/work/.fah/skills/x/SKILL.md'), isNull);
      expect(
        builtinSkillTextAt('builtin://skills/create-goal/other.md'),
        isNull,
      );
    });

    test('the read tool serves the builtin:// path', () async {
      final skill = builtinSkills().firstWhere(
        (s) => s.name == 'self-settings',
      );
      final tools = [
        for (final tool in builtinTools(env, sqlite: null))
          if (tool.name == 'read') tool,
      ];
      expect(tools, hasLength(1));
      final result = await tools.single.execute(
        {'path': skill.filePath},
        null,
        null,
      );
      final text = [
        for (final block in result.content)
          if (block is TextContent) block.text,
      ].join('\n');
      expect(text, contains('name: self-settings'));
    });
  });
}

/// S5 drift guard (issue #29, reworked by #1151): every first-party skill
/// under `.fah/skills/` reaches app sessions EITHER as a package built-in
/// (embedded by `scripts/gen_prompts.dart` into `builtinSkillFiles`) OR —
/// for app-only skills with no package embedding — as a bundled asset
/// (`flutter_app/assets/skills/`, listed in the app's pubspec and seeded
/// into sessions by `AgentService._seedBundledSkills`). Skills that are
/// both bundled and embedded are forbidden: the seeded project copy would
/// shadow the built-in with a duplicate listing.
///
/// VM-only (reads files from disk).
@TestOn('vm')
library;

import 'dart:io';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

void main() {
  final skills = Directory('.fah/skills');
  final bundled = Directory('flutter_app/assets/skills');
  final embedded = builtinSkills().map((s) => s.name).toSet();

  test('every first-party skill ships as a builtin or a bundled app asset', () {
    expect(skills.existsSync(), isTrue, reason: '.fah/skills missing');
    final names =
        skills
            .listSync()
            .whereType<Directory>()
            .map((d) => d.uri.pathSegments.reversed.toList()[1])
            .toList()
          ..sort();
    expect(names, isNotEmpty);

    final pubspec = File('flutter_app/pubspec.yaml').readAsStringSync();
    for (final name in names) {
      final asset = File('flutter_app/assets/skills/$name/SKILL.md');
      if (embedded.contains(name)) {
        // #1151: shipped inside the core package - invocable on every
        // surface. The .fah/skills copy stays as a project override
        // (non-goal to migrate), but a bundled app copy would shadow the
        // builtin with a duplicate listing.
        expect(
          asset.existsSync(),
          isFalse,
          reason:
              'skill "$name" is embedded as a package builtin; the '
              'bundled app copy shadows it with a duplicate listing - '
              'delete flutter_app/assets/skills/$name/',
        );
        expect(
          pubspec.contains('assets/skills/$name/'),
          isFalse,
          reason:
              'skill "$name" is embedded as a package builtin but still '
              'listed in flutter_app/pubspec.yaml assets',
        );
        continue;
      }
      // Not embedded: project override. If the app bundles it anyway,
      // the old mirror rules apply; otherwise project-only is fine.
      if (!asset.existsSync()) continue;
      expect(
        pubspec,
        contains('assets/skills/$name/SKILL.md'),
        reason:
            'skill "$name" is bundled but not listed in '
            'flutter_app/pubspec.yaml assets',
      );
    }
  });

  test('bundled SKILL.md copies are byte-identical to the source skill', () {
    if (!bundled.existsSync()) return; // gh-1164: no bundled skills left
    for (final dir in bundled.listSync().whereType<Directory>()) {
      final name = dir.uri.pathSegments.reversed.toList()[1];
      final source = File('.fah/skills/$name/SKILL.md');
      final copy = File('flutter_app/assets/skills/$name/SKILL.md');
      if (!source.existsSync()) continue; // app-only skill, no source pin
      expect(
        copy.readAsStringSync(),
        source.readAsStringSync(),
        reason:
            'flutter_app/assets/skills/$name/SKILL.md drifted from '
            '.fah/skills/$name/SKILL.md - re-copy the source skill '
            '(the source of truth is .fah/skills/)',
      );
    }
  });

  test('AgentService._seedBundledSkills no longer seeds any bundled skill', () {
    // gh-1164 Part A: the last bundled skill (js-apps) moved into the
    // package builtins, so the seeder has nothing left to seed — it only
    // retires the stale seeded copies. Guard the retirement: the source
    // must not grow a bundled-seeding map again (rootBundle.loadString
    // of an assets/skills path), and any skill re-added under
    // flutter_app/assets/skills/ must come back through the drift rules
    // in the tests above.
    final source = File(
      'flutter_app/lib/services/agent_service_skills.dart',
    ).readAsStringSync();
    final decl = source.indexOf('Future<void> _seedBundledSkills');
    expect(decl, greaterThanOrEqualTo(0), reason: 'seeder missing');
    final bodyEnd = source.indexOf('\n}\n', decl);
    expect(bodyEnd, greaterThan(decl), reason: 'seeder body missing');
    final body = source.substring(decl, bodyEnd);
    expect(
      body,
      isNot(contains('rootBundle.loadString')),
      reason:
          '_seedBundledSkills seeds from the asset bundle again - the '
          'bundled-skill machinery was retired by gh-1164 Part A',
    );
    expect(
      body,
      isNot(contains('assets/skills')),
      reason:
          '_seedBundledSkills references assets/skills again - bundled '
          'skills were retired by gh-1164 Part A',
    );
  });
}

