Future<String> renderBuiltinSkills(String repoRoot) async {
  final dir = Directory('$repoRoot/prompts/skills');
  final names =
      (dir.existsSync() ? dir.listSync() : <FileSystemEntity>[])
          .whereType<Directory>()
          .map((d) => d.uri.pathSegments.reversed.toList()[1])
          .toList()
        ..sort();
