    test('current tree passes: every prompts/skills/<name>/SKILL.md is full', () {
      expect(
        guard.builtinSkillSourceViolations('.'),
        completion(isEmpty),
        reason:
            'a prompts/skills/<name>/SKILL.md source is missing or under '
