/// Release gate for built-in skill PACKAGED CONTENT (gh-1275 AC3).
///
/// 1.0.512 shipped the apps with the skill DIRECTORY STRUCTURE present but
/// the SKILL.md CONTENT missing (the bundled-asset seeder, #1151's app-side
/// half) — and no check noticed because every existing guard asserted
/// directory presence, never byte content. The packaging mechanism is
/// compiled-in Dart now (gh-1164: `scripts/gen_prompts.dart` embeds every
/// `prompts/skills/<name>/SKILL.md` into `builtinSkillFiles`), so the check
/// runs against the exact bytes every host (iOS/macOS/Android/web/CLI)
/// compiles in:
///
/// ```sh
/// dart run scripts/verify_builtin_skills.dart   # exit 1 + named violations
/// ```
///
/// Wired into the app build workflows (build-mobile.yml, build-macos.yml,
/// pages.yml) as a fail-fast pre-build step; the same checker runs on every
/// PR through `test/skills/builtin_skill_packaging_guard_test.dart`
/// (gh-798 selftest pattern: the gate cannot rot silently).
library;

import 'dart:io';

import 'package:flutter_agent_harness/src/prompts/prompts.g.dart'
    show builtinSkillFiles;

/// Byte floor for a shipped SKILL.md (gh-1275 AC3: "non-empty SKILL.md,
/// byte size > some floor"). The smallest built-in today is
/// create-goal at ~8.3 KB — the floor only has to catch the incident
/// class (empty / whitespace / frontmatter-only stubs), not measure size.
const builtinSkillMinBytes = 1024;

/// Named verdicts for one name → content map (the packaged artifact's
/// built-in skill table). Empty list = the artifact ships usable content
/// for every built-in skill.
List<String> builtinSkillContentViolations(
  Map<String, String> builtinFiles, {
  int minBytes = builtinSkillMinBytes,
}) {
  final violations = <String>[];
  if (builtinFiles.isEmpty) {
    violations.add('packaged artifact ships NO built-in skills at all');
  }
  for (final entry in [...builtinFiles.entries]..sortByKey...) {
    final bytes = utf8.encode(entry.value).length;  // need dart:convert
    if (entry.value.trim().isEmpty) {
      violations.add('built-in skill "${entry.key}": SKILL.md ships EMPTY (0 bytes of content)');
    } else if (bytes < minBytes) {
      violations.add('built-in skill "${entry.key}": SKILL.md is $bytes bytes, below the ${minBytes}-byte floor — frontmatter-only stub?');
    }
  }
  return violations;
}
